#!/usr/bin/env Rscript

args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 4L) stop("usage: retina_diag.R eye1.mtx.gz eye2.mtx.gz genes.txt.gz outdir")

suppressPackageStartupMessages(library(Matrix))

open_text <- function(path) {
  if (grepl("\\.gz$", path, ignore.case = TRUE)) gzfile(path, open = "rt") else file(path, open = "rt")
}

read_genes <- function(path) {
  con <- open_text(path)
  on.exit(close(con), add = TRUE)
  d <- read.delim(con, header = TRUE, sep = "\t", quote = "", comment.char = "",
                  stringsAsFactors = FALSE, check.names = FALSE)
  if (ncol(d) < 1L) stop("gene table has no columns")
  ids <- as.character(d[[1L]])
  syms <- if (ncol(d) >= 2L) as.character(d[[2L]]) else ids
  syms[is.na(syms) | syms == ""] <- ids[is.na(syms) | syms == ""]
  list(ids = ids, symbols = syms)
}

read_mtx <- function(path) {
  con <- open_text(path)
  on.exit(close(con), add = TRUE)
  z <- readMM(con)
  as(z, "dgCMatrix")
}

genes <- read_genes(args[[3L]])
